-- 셋을 나란히 선언한다

public interface MemberRepository extends JpaRepository<Member, Long> {
    Page<Member>  findPageByAge(int age, Pageable pageable);
    Slice<Member> findSliceByAge(int age, Pageable pageable);
    List<Member>  findListByAge(int age, Pageable pageable);
}

--   5.1절대로 Page/Slice/List 만 다르다


-- Page

@Test
@Transactional
void page() {
    em.clear();
    Page<Member> p = memberRepository.findPageByAge(10,
            PageRequest.of(0, 3, Sort.by("username")));
    System.out.println("행:   " + p.getContent().size());
    System.out.println("전체: " + p.getTotalElements());
    System.out.println("쪽수: " + p.getTotalPages());
}

Hibernate:
    select ... from member m1_0 where m1_0.age=?
    order by m1_0.username offset ? rows fetch first ? rows only
