-- 세 개를 한 번에 센다

@Test
@Transactional
void 쿼리_수() {
    for (String kind : List.of("page", "slice", "list")) {
        em.clear();
        long n = counter.count(() -> {
            Pageable req = PageRequest.of(0, 3, Sort.by("username"));
            switch (kind) {
                case "page"  -> memberRepository.findPageByAge(10, req)
                                    .getTotalElements();
                case "slice" -> memberRepository.findSliceByAge(10, req)
                                    .hasNext();
                default      -> memberRepository.findListByAge(10, req).size();
            }
        });
        System.out.printf("%-6s %d개%n", kind, n);
    }
}

