-- 시간을 잰다

@Test
@Transactional
void 시간() {
    em.createQuery("delete from Member").executeUpdate();
    Team t = new Team("A"); em.persist(t);
    for (int i = 0; i < 20000; i++) {
        Member m = new Member("p" + i, 10); m.setTeam(t); em.persist(m);
    }
    em.flush(); em.clear();

    for (String kind : List.of("조인", "분리", "slice")) {
        em.clear();
        long t0 = System.nanoTime();
        Pageable req = PageRequest.of(0, 20);
        switch (kind) {
            case "조인"  -> memberRepository.withJoin(req).getTotalElements();
            case "분리"  -> memberRepository.withCountQuery(req)
                                .getTotalElements();
            default     -> memberRepository.findSliceByAge(10, req).hasNext();
        }
        System.out.printf("%-6s %d ms%n", kind, (System.nanoTime()-t0)/1_000_000);
    }
}

조인   41 ms
분리   26 ms
slice   4 ms

